declare r fib.messages%rowtype;
begin
select * into r from jsonb_populate_record(null::fib.messages, '{"id":"a0bc41fc-d7e3-5abc-ae9d-ffffa15be6be","event_id":"3b6bcf3a-8bba-5546-ac4f-ea3a1b2ef551","slug":"demo-20261013-r069","title":"[ENTWICKLUNG demo-20261013] Hundewiese: Neue Vorlage nennt Schallschutzkosten und Park-Alternative","teaser":"Die öffentlich freigegebene Vorlage konkretisiert Schallschutz, Kosten und Betriebsfragen und stellt einer eingezäunten Hundewiese eine offene Park- und Freilauffläche als Alternative gegenüber.","body":"Der Gemeinderat hatte am 26. März 2026 mehrheitlich beschlossen, an einer Hundewiese östlich des Friedhofs festzuhalten und dafür etwa 1.000 m² vorzusehen. Die schalltechnische Untersuchung kam anschließend zu dem Ergebnis, dass eine uneingeschränkte Nutzung ohne Schutzmaßnahmen nicht möglich wäre. Vorgesehen wären unter anderem eine auf etwa 85 × 12 Meter zugeschnittene Fläche, zeitliche Nutzungsbeschränkungen und eine rund 50 Meter lange sowie 1,5 Meter hohe schalldichte Abschirmung. Für diese Abschirmung nennt die Verwaltung nach einer Markterkundung Angebote von etwa 15.200 bis 30.000 Euro; ein deutlich höheres Angebot lag bei rund 115.000 Euro.\n\nZusätzlich zu den Investitionskosten nennt die Vorlage offene Betriebsfragen: Wer die Anlage täglich auf- und zusperrt, wie die Nutzungszeiten kontrolliert und Verstöße behandelt werden, ist noch nicht geklärt. Die Verwaltung weist außerdem darauf hin, dass ihr keine belastbaren Zahlen zum konkreten Bedarf einer Hundewiese vorliegen; im Gemeindegebiet sind 372 Hunde gemeldet.\n\nDie Vorlage dokumentiert zugleich Einwände aus der Bürgerschaft, insbesondere der Initiative „Lebenswertes Feldkirchen – Pfoten weg vom Wohngebiet“. Diese betreffen unter anderem Bedarf, Kosten, Nähe zu Wohnbebauung und Friedhof, Nutzung durch Kinder sowie zusätzlichen Parkdruck. Die Verwaltung beantwortet einzelne Punkte, ohne damit die politische Abwägung vorwegzunehmen.\n\nAls Alternative wird die Prüfung einer offenen Park- und Freilauffläche beschrieben, in die auch Hundebesitzer einbezogen werden könnten. Genannt werden als mögliche Gestaltungselemente unter anderem Tiny Forest, Biodiversitätsgarten und ein öffentlicher Trinkwasserbrunnen. Dabei handelt es sich um eine Prüf- und Gestaltungsoption, nicht um eine bereits beschlossene Planung.\n\nDie fortgeschriebene Beschlussvorlage wurde im RIS öffentlich freigegeben. Ein zugehöriger Tagesordnungspunkt bzw. bestätigter Sitzungstermin ist in der veröffentlichten Tagesordnung derzeit nicht nachgewiesen.","editorial_assessment":"Positiv ist zunächst, wie ausführlich die Verwaltung den Stand der Diskussion dokumentiert. Die Vorlage macht Gutachten, Kosten und praktische Betriebsfragen sichtbar, greift Einwände aus der Bürgerschaft auf und stellt verschiedene Nutzungsmöglichkeiten gegenüber. Gerade bei einem kontroversen lokalen Thema schafft eine solche transparente Entscheidungsgrundlage gute Voraussetzungen dafür, unterschiedliche Interessen nachvollziehen und abwägen zu können.\n\nAuch die von der Verwaltung eingebrachte Alternative verdient aus grüner Sicht Aufmerksamkeit. Eine offen zugängliche Grünfläche, die beispielsweise einen Tiny Forest, einen Biodiversitätsgarten und einen Trinkwasserbrunnen miteinander verbindet und zugleich Möglichkeiten für Hundehalter berücksichtigt, könnte mehrere Funktionen auf derselben Fläche zusammenbringen: Erholung und Begegnung, Artenvielfalt und Klimaanpassung. Solche Grünflächen, Bäume, Biodiversitätsmaßnahmen und Trinkbrunnen entsprechen wichtigen Zielen grüner Kommunalpolitik.\n\nDamit ist noch keine Entscheidung über die konkrete Gestaltung der Fläche vorweggenommen. Entscheidend wäre, die unterschiedlichen Nutzungsinteressen und die ökologischen Möglichkeiten in der weiteren Planung gemeinsam zu betrachten.","status":"draft","approved_at":null,"published_at":null,"withdrawn_at":null}'::jsonb);
if exists(select 1 from fib.messages t where t.id = r.id) then
  if not exists(select 1 from fib.messages t where t.id = r.id and t.id is not distinct from r.id and t.event_id is not distinct from r.event_id and t.slug is not distinct from r.slug and t.title is not distinct from r.title and t.teaser is not distinct from r.teaser and t.body is not distinct from r.body and t.editorial_assessment is not distinct from r.editorial_assessment and t.status is not distinct from r.status and t.approved_at is not distinct from r.approved_at and t.published_at is not distinct from r.published_at and t.withdrawn_at is not distinct from r.withdrawn_at) then
    raise exception 'Import conflict: messages a0bc41fc-d7e3-5abc-ae9d-ffffa15be6be';
  end if;
else
